import java.io.*;
import java.util.*;

public class Solution {
    public static class Solver {
        public static class MaxFlow {
            class Edge {
                int to, rev;
                long cap, flow;
                Edge(int to, int rev, long cap) {
                    this.to = to;
                    this.rev = rev;
                    this.cap = cap;
                }
            }
            List<Edge>[] graph;
            MaxFlow(int n) {
                graph = new List[n];
                for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
            }
            void addEdge(int s, int t, long cap) {
                graph[s].add(new Edge(t, graph[t].size(), cap));
                graph[t].add(new Edge(s, graph[s].size() - 1, 0));
            }
            boolean bfs(int src, int dest, int[] dist) {
                Arrays.fill(dist, -1);
                dist[src] = 0;
                int[] q = new int[graph.length];
                int qs = 0;
                q[qs++] = src;
                for (int i = 0; i < qs; i++) {
                    int u = q[i];
                    for (Edge e : graph[u]) {
                        if (dist[e.to] < 0 && e.flow < e.cap) {
                            dist[e.to] = dist[u] + 1;
                            q[qs++] = e.to;
                        }
                    }
                }
                return dist[dest] >= 0;
            }
            long dfs(int[] ptr, int[] dist, int dest, int u, long f) {
                if (u == dest) return f;
                for (; ptr[u] < graph[u].size(); ++ptr[u]) {
                    Edge e = graph[u].get(ptr[u]);
                    if (dist[e.to] == dist[u] + 1 && e.flow < e.cap) {
                        long df = dfs(ptr, dist, dest, e.to, Math.min(f, e.cap - e.flow));
                        if (df > 0) {
                            e.flow += df;
                            graph[e.to].get(e.rev).flow -= df;
                            return df;
                        }
                    }
                }
                return 0;
            }
            long maxFlow(int src, int dest) {
                long flow = 0;
                int[] dist = new int[graph.length];
                while (bfs(src, dest, dist)) {
                    int[] ptr = new int[graph.length];
                    while (true) {
                        long df = dfs(ptr, dist, dest, src, Long.MAX_VALUE);
                        if (df == 0) break;
                        flow += df;
                    }
                }
                return flow;
            }
        }

        public static class MinCostFlow {
            class Edge {
                int to, flow, cap, cost, rev;
                Edge(int to, int cap, int cost, int rev) {
                    this.to = to;
                    this.cap = cap;
                    this.cost = cost;
                    this.rev = rev;
                }
            }
            List<Edge>[] graph;
            MinCostFlow(int n) {
                graph = new List[n];
                for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
            }
            void addEdge(int s, int t, int cap, int cost) {
                graph[s].add(new Edge(t, cap, cost, graph[t].size()));
                graph[t].add(new Edge(s, 0, -cost, graph[s].size() - 1));
            }
            void bellmanFord(int s, int[] dist, int[] prevNode, int[] prevEdge, int[] curFlow) {
                int n = graph.length;
                Arrays.fill(dist, 0, n, Integer.MAX_VALUE);
                dist[s] = 0;
                curFlow[s] = Integer.MAX_VALUE;
                boolean[] inQ = new boolean[n];
                int[] q = new int[n];
                int qt = 0;
                q[qt++] = s;
                for (int qh = 0; (qh - qt) % n != 0; qh++) {
                    int u = q[qh % n];
                    inQ[u] = false;
                    for (int i = 0; i < graph[u].size(); i++) {
                        Edge e = graph[u].get(i);
                        if (e.flow >= e.cap) continue;
                        int v = e.to;
                        int nd = dist[u] + e.cost;
                        if (dist[v] > nd) {
                            dist[v] = nd;
                            prevNode[v] = u;
                            prevEdge[v] = i;
                            curFlow[v] = Math.min(curFlow[u], e.cap - e.flow);
                            if (!inQ[v]) {
                                inQ[v] = true;
                                q[qt++ % n] = v;
                            }
                        }
                    }
                }
            }
            int[] minCostFlow(int s, int t, int maxf) {
                int n = graph.length;
                int[] dist = new int[n];
                int[] curFlow = new int[n];
                int[] prevEdge = new int[n];
                int[] prevNode = new int[n];
                int flow = 0, cost = 0;
                while (flow < maxf) {
                    bellmanFord(s, dist, prevNode, prevEdge, curFlow);
                    if (dist[t] == Integer.MAX_VALUE) break;
                    int df = Math.min(curFlow[t], maxf - flow);
                    flow += df;
                    for (int v = t; v != s; v = prevNode[v]) {
                        Edge e = graph[prevNode[v]].get(prevEdge[v]);
                        e.flow += df;
                        graph[v].get(e.rev).flow -= df;
                        cost += df * e.cost;
                    }
                }
                return new int[]{flow, cost};
            }
        }

        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int N = sc.nextInt();
            int M = sc.nextInt();
            int K = sc.nextInt();
            int C = sc.nextInt();
            int D = sc.nextInt();
            int[] pos = new int[N];
            for (int i = 0; i < K; i++) pos[sc.nextInt() - 1]++;
            int T = 100;
            MinCostFlow mf = new MinCostFlow((T + 1) * N + 2);
            for (int i = 0; i < N; i++) if (pos[i] > 0) mf.addEdge(0, i + 1, pos[i], 0);
            for (int i = 0; i < T; i++) for (int j = 0; j < N; j++) mf.addEdge(1 + i * N + j, 1 + (i + 1) * N + j, K, 0);
            for (int i = 0; i <= T; i++) for (int j = 1; j <= K; j++) mf.addEdge(1 + i * N, (T + 1) * N + 1, 1, C * i);
            for (int i = 0; i < M; i++) {
                int a = sc.nextInt() - 1, b = sc.nextInt() - 1;
                for (int j = 0; j < T; j++) {
                    int cost = 0;
                    for (int l = 1; l <= K; l++) {
                        mf.addEdge(1 + j * N + a, 1 + (j + 1) * N + b, 1, l * l * D - cost);
                        mf.addEdge(1 + j * N + b, 1 + (j + 1) * N + a, 1, l * l * D - cost);
                        cost = l * l * D;
                    }
                }
            }
            int[] res = mf.minCostFlow(0, (T + 1) * N + 1, K);
            System.err.println(res[0]);
            pw.println(res[1]);
        }
    }

    static long TIME_START, TIME_END;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
        Runtime rt = Runtime.getRuntime();
        long memBefore = rt.totalMemory() - rt.freeMemory();
        TIME_START = System.currentTimeMillis();
        new Solver().solve(sc, pw);
        TIME_END = System.currentTimeMillis();
        long memAfter = rt.totalMemory() - rt.freeMemory();
        pw.close();
        System.err.println("Memory increased: " + (memAfter - memBefore) / 1000000);
        System.err.println("Time used: " + (TIME_END - TIME_START) + ".");
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;
        Scanner(InputStream s) { br = new BufferedReader(new InputStreamReader(s)); }
        Scanner(FileReader s) throws FileNotFoundException { br = new BufferedReader(s); }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }
        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
        String nextLine() throws IOException { return br.readLine(); }
        double nextDouble() throws IOException { return Double.parseDouble(next()); }
        boolean ready() throws IOException { return br.ready(); }
    }
}
